import { test, expect } from '@playwright/test';
import path from 'path';

test.describe('Profile Picture Upload', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the profile page
    await page.goto('/profile');

    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should upload a profile picture and display preview', async ({ page }) => {
    // Find the file input element
    const fileInput = page.locator('input[type="file"]');

    // Create a test image file path
    const testImagePath = path.join(__dirname, 'fixtures', 'test-profile-image.png');

    // Set the file input value
    await fileInput.setInputFiles(testImagePath);

    // Wait for the preview to appear
    const preview = page.getByRole('img', { name: /profile picture|preview/i });
    await expect(preview).toBeVisible();

    // Verify the preview image has the correct src
    await expect(preview).toHaveAttribute('src', /blob:|data:/);
  });

  test('should display upload button and handle file selection', async ({ page }) => {
    // Find and verify the upload button exists
    const uploadButton = page.getByRole('button', { name: /upload|choose|select.*picture/i });
    await expect(uploadButton).toBeVisible();

    // Click the upload button to trigger file input
    await uploadButton.click();

    // Verify file input is present
    const fileInput = page.locator('input[type="file"]');
    await expect(fileInput).toBeVisible();
  });

  test('should show error message for invalid file type', async ({ page }) => {
    // Find the file input
    const fileInput = page.locator('input[type="file"]');

    // Create a test text file path
    const testFilePath = path.join(__dirname, 'fixtures', 'test-file.txt');

    // Attempt to set invalid file type
    await fileInput.setInputFiles(testFilePath);

    // Wait for error message
    const errorMessage = page.getByText(/invalid|unsupported|only.*image/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should display preview with correct dimensions', async ({ page }) => {
    // Find the file input
    const fileInput = page.locator('input[type="file"]');

    // Upload a test image
    const testImagePath = path.join(__dirname, 'fixtures', 'test-profile-image.png');
    await fileInput.setInputFiles(testImagePath);

    // Wait for preview image
    const preview = page.getByRole('img', { name: /profile picture|preview/i });
    await expect(preview).toBeVisible();

    // Verify preview dimensions
    const boundingBox = await preview.boundingBox();
    expect(boundingBox).not.toBeNull();
    expect(boundingBox?.width).toBeGreaterThan(0);
    expect(boundingBox?.height).toBeGreaterThan(0);
  });

  test('should allow replacing uploaded picture', async ({ page }) => {
    // Upload first image
    const fileInput = page.locator('input[type="file"]');
    const testImagePath = path.join(__dirname, 'fixtures', 'test-profile-image.png');
    await fileInput.setInputFiles(testImagePath);

    // Verify first preview is visible
    const preview = page.getByRole('img', { name: /profile picture|preview/i });
    await expect(preview).toBeVisible();

    // Get the initial src
    const initialSrc = await preview.getAttribute('src');

    // Upload a different image
    const secondImagePath = path.join(__dirname, 'fixtures', 'test-profile-image-2.png');
    await fileInput.setInputFiles(secondImagePath);

    // Verify preview is still visible
    await expect(preview).toBeVisible();

    // Verify the src has changed (new image loaded)
    const newSrc = await preview.getAttribute('src');
    expect(newSrc).not.toBe(initialSrc);
  });

  test('should show loading state during upload', async ({ page }) => {
    // Find the file input
    const fileInput = page.locator('input[type="file"]');

    // Upload image
    const testImagePath = path.join(__dirname, 'fixtures', 'test-profile-image.png');
    await fileInput.setInputFiles(testImagePath);

    // Check for loading indicator
    const loadingIndicator = page.getByRole('status', { name: /uploading|loading/i });

    // Loading indicator might appear briefly, so we check if it exists
    const isVisible = await loadingIndicator.isVisible().catch(() => false);

    // Wait for upload to complete
    const preview = page.getByRole('img', { name: /profile picture|preview/i });
    await expect(preview).toBeVisible();
  });

  test('should persist uploaded picture after page reload', async ({ page }) => {
    // Upload an image
    const fileInput = page.locator('input[type="file"]');
    const testImagePath = path.join(__dirname, 'fixtures', 'test-profile-image.png');
    await fileInput.setInputFiles(testImagePath);

    // Wait for preview
    const preview = page.getByRole('img', { name: /profile picture|preview/i });
    await expect(preview).toBeVisible();

    // Get the src before reload
    const srcBeforeReload = await preview.getAttribute('src');

    // Reload the page
    await page.reload();

    // Wait for page to load
    await page.waitForLoadState('networkidle');

    // Verify preview is still visible
    const previewAfterReload = page.getByRole('img', { name: /profile picture|preview/i });
    await expect(previewAfterReload).toBeVisible();

    // Verify the image is still there (src should be a valid URL or data URI)
    const srcAfterReload = await previewAfterReload.getAttribute('src');
    expect(srcAfterReload).toBeTruthy();
  });
});
